const root = $input.first().json;
const u = root.callback_query || root;
const cqid = u.id != null ? u.id : null;
if (!u || !u.data) return [{ json: { skip: true, callback_query_id: cqid, answer_text: 'Brak danych.' } }];
const data = String(u.data || '');
const fromId = u.from && u.from.id != null ? String(u.from.id) : '';
let allowed = '';
try { allowed = String($env.TELEGRAM_OPERATOR_CHAT_ID || '').trim(); } catch (e) {}
if (!allowed || fromId !== allowed) {
  return [{ json: { skip: true, callback_query_id: cqid, answer_text: 'Brak uprawnien.' } }];
}
let action = '';
let leadId = '';
if (data.startsWith('ap:')) { action = 'approve'; leadId = data.slice(3).trim(); }
else if (data.startsWith('rj:')) { action = 'reject'; leadId = data.slice(3).trim(); }
else return [{ json: { skip: true, callback_query_id: cqid, answer_text: 'Nieznana akcja.' } }];
if (!leadId || leadId.length < 32) return [{ json: { skip: true, callback_query_id: cqid, answer_text: 'Zly ID.' } }];
const opId = u.from && u.from.id != null ? u.from.id : null;
return [{ json: { skip: false, action, lead_id: leadId, callback_query_id: cqid, message_chat_id: u.message && u.message.chat ? u.message.chat.id : null, message_id: u.message && u.message.message_id, operator_telegram_user_id: opId } }];
